function bhranti_plugin_error( $result, $label, $code = null ) { bhranti_plugin_check( is_wp_error( $result ) && ( null === $code || $code === $result->get_error_code() ), $label . ( is_wp_error( $result ) ? ' (' . $result->get_error_code() . ')' : '' ) ); }
function bhranti_plugin_command( $method, $path, $params = array() ) { return array( 'tool' => 'plugin_request', 'args' => array( 'method' => $method, 'path' => $path, 'params' => $params ) ); }
function bhranti_plugin_rest( $method, $path, $params = array(), $json = false ) { $r = new WP_REST_Request( $method, '/bhranti/v1' . $path ); if ( $json ) { $r->set_header( 'Content-Type', 'application/json' ); $r->set_body( wp_json_encode( $params ) ); } else { $r->set_body_params( $params ); } return rest_do_request( $r ); }
function bhranti_plugin_raw_option( $name ) { global $wpdb; return $wpdb->get_row( $wpdb->prepare( "SELECT option_value,autoload FROM {$wpdb->options} WHERE option_name=%s", $name ), ARRAY_A ); }
