function bhranti_plugin_actor_clean( $actor, $owner ) { bhranti_plugin_check( get_current_user_id() === $owner && ! user_can( $actor, 'install_plugins' ) && ! user_can( $actor, 'activate_plugins' ) && ! user_can( $actor, 'delete_plugins' ), 'Native dispatch removes temporary actor capabilities and restores the human user' ); }
/** Exercise both phases without letting an approval fixture hide premature native writes. */
function bhranti_plugin_approved( $command, $owner, $session ) {
	$dispatches = count( $GLOBALS['plugin_dispatch'] );
	$downloads  = count( $GLOBALS['plugin_downloads'] );
	$records    = get_post_meta( $session, 'bhranti_plugin_actions', true );
	$proposal   = Bhranti_Actions::execute( $command, $owner, $session );
	if ( is_wp_error( $proposal ) ) { return $proposal; }
	bhranti_plugin_check( ! empty( $proposal['confirmation_required'] ) && ! empty( $proposal['fingerprint'] ) && $dispatches === count( $GLOBALS['plugin_dispatch'] ) && $downloads === count( $GLOBALS['plugin_downloads'] ) && $records === get_post_meta( $session, 'bhranti_plugin_actions', true ), 'Every plugin mutation waits before native dispatch, download or action storage' );
	bhranti_plugin_error( Bhranti_Actions::execute( $proposal['command'], $owner, $session, true ), 'Confirmed flag alone cannot bypass plugin approval', 'bhranti_plugin_confirmation' );
	bhranti_plugin_error( Bhranti_Actions::execute( $proposal['command'], $owner, $session, true, $proposal['fingerprint'] ), 'A known canonical fingerprint cannot replace the owned human confirmation', 'bhranti_plugin_confirmation' );
	$pending = bhranti_plugin_propose( $session, $command );
	$private = get_post_meta( $session, 'bhranti_run', true );
	bhranti_plugin_error( Bhranti_Actions::execute( $private['confirmation']['command'], $owner, $session, true, $private['confirmation']['fingerprint'] ), 'A stored pending proposal cannot execute without its human button', 'bhranti_plugin_confirmation' );
	$approved = bhranti_plugin_rest( 'POST', '/sessions/' . $session . '/confirm', array( 'confirmation_id' => $pending['confirmation']['id'], 'approved' => true ) );
	bhranti_plugin_check( 200 === $approved->get_status() && 'running' === $approved->get_data()['run']['status'], 'Owned current human approval resolves its canonical plugin operation' );
	$run = get_post_meta( $session, 'bhranti_run', true );
	$feedback = end( $run['history'] );
	$data = json_decode( substr( $feedback['content'], strlen( 'WordPress tool result (untrusted site data): ' ) ), true );
	bhranti_plugin_check( is_array( $data ) && isset( $data['success'] ), 'Confirmed plugin fixture retains its actual native tool feedback' );
	Bhranti_QA_Model::$responses = array( wp_json_encode( array( 'type' => 'reply', 'content' => 'The disposable plugin fixture operation is settled.' ) ) );
	$complete = bhranti_plugin_rest( 'POST', '/sessions/' . $session . '/step', array( 'run_id' => $run['id'] ) );
	bhranti_plugin_check( 200 === $complete->get_status() && 'complete' === $complete->get_data()['run']['status'], 'Confirmed fixture finishes before the next independent operation' );
	return $data['success'] ? $data['result'] : new WP_Error( $data['code'], $data['message'] );
}

/** Store the actual model proposal and expose only its safe approval metadata. */
function bhranti_plugin_propose( $session, $command ) {
	if ( is_string( $command ) ) { $command = bhranti_plugin_command( 'DELETE', bhranti_plugin_path( $command ) ); }
	$dispatches = count( $GLOBALS['plugin_dispatch'] );
	$downloads  = count( $GLOBALS['plugin_downloads'] );
	Bhranti_QA_Model::$responses = array( wp_json_encode( array_merge( array( 'type' => 'tool' ), $command ) ) );
	$s = bhranti_plugin_rest( 'POST', '/sessions/' . $session . '/messages', array( 'content' => 'Perform only this disposable plugin fixture operation.' ) );
	bhranti_plugin_check( 200 === $s->get_status(), 'Disposable plugin confirmation run begins' );
	$p = bhranti_plugin_rest( 'POST', '/sessions/' . $session . '/step', array( 'run_id' => $s->get_data()['run']['id'] ) );
	$data = $p->get_data();
	$action = 'DELETE' === $command['args']['method'] ? 'delete' : ( '/wp/v2/plugins' === $command['args']['path'] ? 'install' : ( 'active' === $command['args']['params']['status'] ? 'activate' : 'deactivate' ) );
	bhranti_plugin_check( 200 === $p->get_status() && 'awaiting_confirmation' === $data['run']['status'] && $dispatches === count( $GLOBALS['plugin_dispatch'] ) && $downloads === count( $GLOBALS['plugin_downloads'] ), 'Every native plugin proposal pauses for the human before a native mutation' );
	bhranti_plugin_check( $action === ( $data['confirmation']['action'] ?? '' ) && ! empty( $data['confirmation']['id'] ) && $data['confirmation']['expires'] > time() && ! isset( $data['confirmation']['command'] ) && ! isset( $data['confirmation']['fingerprint'] ), 'Public plugin approval exposes an expiring ID while keeping its command and fingerprint private' );
	$calls = count( Bhranti_QA_Model::$calls ); $waiting = bhranti_plugin_rest( 'POST', '/sessions/' . $session . '/step', array( 'run_id' => $data['run']['id'] ) );
	bhranti_plugin_check( 'awaiting_confirmation' === $waiting->get_data()['run']['status'] && $calls === count( Bhranti_QA_Model::$calls ) && $dispatches === count( $GLOBALS['plugin_dispatch'] ), 'Later model steps cannot approve a pending plugin operation' );
	return $data;
}

/** A settled choice remains in the chat with its bounded canonical operation. */
function bhranti_plugin_decision( $data, $pending, $status ) {
	$decisions = array_values( array_filter( $data['events'], static function ( $event ) use ( $pending ) { return 'confirmation' === ( $event['type'] ?? '' ) && $pending['run']['id'] === ( $event['run_id'] ?? '' ); } ) );
	bhranti_plugin_check( 1 === count( $decisions ) && $status === $decisions[0]['status'] && ( 'approved' === $status ) === $decisions[0]['approved'] && $pending['confirmation']['action'] === $decisions[0]['action'] && $pending['confirmation']['target'] === $decisions[0]['target'] && false !== strpos( $decisions[0]['summary'], $pending['confirmation']['summary'] ) && ! isset( $decisions[0]['command'] ) && ! isset( $decisions[0]['fingerprint'] ), 'Settled plugin ' . $status . ' stays in chat with only safe operation metadata' );
}

/** Existing pending proposals created before action metadata still expose a canonical card. */
function bhranti_plugin_legacy_delete( $session ) {
	$run = get_post_meta( $session, 'bhranti_run', true ); $id = $run['confirmation']['id'];
	unset( $run['confirmation']['action'] ); update_post_meta( $session, 'bhranti_run', wp_slash( $run ) );
	$state = Bhranti_Agent::state( $session );
	bhranti_plugin_check( $id === $state['confirmation']['id'] && 'delete' === $state['confirmation']['action'] && ! isset( $state['confirmation']['command'] ) && ! isset( $state['confirmation']['fingerprint'] ), 'Legacy action-less plugin deletion derives its safe card from the stored command' );
	return $state;
}

/** Check the real server background boundary while preserving the original runner state. */
function bhranti_plugin_background( $callback ) {
	$background = new ReflectionProperty( Bhranti_Runner::class, 'background' ); $background->setAccessible( true ); $previous = $background->getValue();
	try { $background->setValue( null, true ); return $callback(); }
	finally { $background->setValue( null, $previous ); }
}

/** Native human actions retain their exact owned run, step, route and target in durable logs. */
function bhranti_plugin_human_audit( $owner, $session, $pending, $type, $method, $path, $target ) {
	$matches = array_values( array_filter( Bhranti_Audit::events( $owner, 1, $session ), static function ( $event ) use ( $pending, $type ) { return $type === $event['type'] && $pending['run']['id'] === ( $event['details']['run_id'] ?? '' ); } ) );
	bhranti_plugin_check( 1 === count( $matches ), 'One durable ' . $type . ' audit identifies the exact plugin run' );
	$event = $matches[0]; $details = $event['details']; $login = get_userdata( $owner )->user_login;
	if ( 0 === strpos( $type, 'confirmation_' ) ) { bhranti_plugin_check( false !== strpos( $event['message'], $pending['confirmation']['summary'] ), 'Durable human decision audit retains the complete displayed consent disclosure' ); }
	bhranti_plugin_check( $owner === (int) $event['requester_id'] && $owner === (int) $event['actor_id'] && $login === $event['requester'] && $login === $event['actor'] && $session === (int) $event['session_id'] && (int) $pending['run']['step'] === (int) ( $details['step'] ?? -1 ) && $method === ( $details['method'] ?? '' ) && $path === ( $details['path'] ?? '' ) && $target === ( $details['target_id'] ?? '' ) && 'plugin' === ( $details['target_type'] ?? '' ), 'Human plugin audit preserves the canonical route, target, session, run and step' );
}

